func toBytes(chars string) ([]byte, error) {
	decoded := make([]byte, 0, len(chars))
	for i := 0; i < len(chars); i++ {
		index := strings.IndexByte(charset, chars[i])
		if index < 0 {
			return nil, ErrNonCharsetChar(chars[i])
		}
		decoded = append(decoded, byte(index))
	}
	return decoded, nil
}
func toBytes(chars string) ([]byte, error) {
	decoded := make([]byte, len(chars))
	for i := 0; i < len(chars); i++ {
		index := charsetRev[chars[i]]
		if index < 0 {
			return nil, ErrNonCharsetChar(chars[i])
		}
		decoded[i] = byte(index)
	}
	return decoded, nil
}

// charsetRev maps a byte to its index in charset, or -1 when it is not in it.
var charsetRev = func() (rev [256]int8) {
	for i := range rev {
		rev[i] = -1
	}
	for i := 0; i < len(charset); i++ {
		rev[charset[i]] = int8(i)
	}
	return rev
}()

